  local units={};for u in p:Units()do units[u:GetID()]={type=u:GetUnitType(),x=u:GetX(),y=u:GetY(),moves=u:GetMoves(),damage=u:GetDamage()}end
  owners[id]={gold=p:GetGold(),faith=p:GetFaith(),cities=p:GetNumCities(),units=units}
 end end
 return {turn=Game.GetGameTurn(),owners=owners}
end
local function audit(name,emit)
 local rows,values,digest=0,0,17
 local columns={};for column in pairs(schema[name])do columns[#columns+1]=column end;table.sort(columns)
 local data={};for row in GameInfo[name]()do data[#data+1]=row end;table.sort(data,function(a,b)return a.ID<b.ID end)
 for _,row in ipairs(data)do
  local native=Game.ReadInfoCacheForTest(name,row.ID);rows=rows+1
  for _,column in ipairs(columns)do
   local reader=schema[name][column];local expected=row[column];local actual=native[column]
   if reader=="GetBool"then expected=expected==true or expected==1
   elseif expected==nil then expected=0
   elseif type(expected)=="boolean"then expected=expected and 1 or 0 end
   local equal=actual==expected
   if reader=="GetFloat"or reader=="GetDouble"then equal=type(actual)=="number"and type(expected)=="number"and math.abs(actual-expected)<=math.max(1,math.abs(expected))*0.000001 end
   assert(equal,"native cache differs: "..name.."/"..row.ID.."/"..column.." expected="..tostring(expected).." actual="..tostring(actual))
   local text=tostring(row.ID)..":"..column..":"..tostring(actual)..";"
   for i=1,#text do digest=(digest*131+string.byte(text,i))%2147483647 end
   values=values+1
  end
  if emit then print("[LEKMOD_CONFIG_CACHE] run=__TEST_RUN__ table="..name.." id="..row.ID.." data="..LekmodScenarioJSON(native))end
 end
 return {rows=rows,values=values,fingerprint=digest}
end
function LekmodScenario.snapshot(p)
 local result={}
 for _,name in ipairs(tables)do result[name]=audit(name,false)end
 return {world=stable(),cache=result}
end
function LekmodScenario.step(p)
 if not before then
  before=LekmodScenarioJSON(stable())
  for _,args in ipairs({{"unknown",0},{"Buildings",-1},{"Buildings",200000}})do local ok=pcall(Game.ReadInfoCacheForTest,args[1],args[2]);assert(not ok,"cache accessor accepted invalid input")end
  LekmodScenarioRecord("cache-boundary-guards","PASS","unknown table and negative/out-of-range indices rejected without state changes")
 end
 local name=tables[cursor]
 if name then local result=audit(name,true);LekmodScenarioRecord("cache-"..name,"PASS","native getter/SQL parity rows="..result.rows.." values="..result.values);cursor=cursor+1;return false end
 assert(LekmodScenarioJSON(stable())==before,"read-only cache audit changed observed world state")
 LekmodScenarioRecord("cache-read-only","PASS","turn, treasury/faith, city counts and unit identities/positions/moves/damage unchanged")
 return true
end
